#!/usr/bin/env node
/**
 * Copy static admin HTML pages from src/_admin/ to out/_admin/.
 *
 * Phase 11: Old admin renamed to _admin/ (was src/admin/ → src/_admin/) per ADR-003.
 * Old admin stays as 30-day rollback entry per ADR-003.
 * New CMS at /admin/* is generated by Next.js static export (src/app/admin/*).
 *
 * Next.js static export (`output: 'export'`) only processes routes under
 * src/app/. The admin pages at src/_admin/ are static HTML files served at
 * /_admin/* — they need this explicit copy step to make it into the
 * Cloudflare Pages deployment bundle.
 *
 * Wired up via npm postbuild script — runs automatically after `next build`.
 */
import { cp, mkdir } from 'fs/promises';
import { existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const ROOT = join(__dirname, '..');
const SRC = join(ROOT, 'src', '_admin');
const DST = join(ROOT, 'out', '_admin');

const TAG = '[copy-admin]';

if (!existsSync(SRC)) {
  console.log(`${TAG} no src/_admin/ — skipping`);
  process.exit(0);
}

if (!existsSync(join(ROOT, 'out'))) {
  console.error(`${TAG} ⚠ out/ does not exist — did next build fail?`);
  process.exit(1);
}

await mkdir(DST, { recursive: true });
await cp(SRC, DST, { recursive: true, dereference: true });
console.log(`${TAG} copied ${SRC} → ${DST}`);
